import {
  type FocusEvent,
  type KeyboardEvent,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from 'react';

export interface NameComboboxOption {
  description?: string;
  keywords?: string[];
  label: string;
  value: string;
}

interface NameComboboxProps {
  dependencyKey: string;
  entityName: string;
  inputValue: string;
  label: string;
  loadOptions(query: string, signal: AbortSignal): Promise<NameComboboxOption[]>;
  onInputChange(value: string): void;
  onSelectionChange(option: NameComboboxOption | null): void;
  onSelectionResolved(option: NameComboboxOption | null): void;
  placeholder?: string | undefined;
  selectedValue: string;
  validationMessage?: string | undefined;
}

type OptionsState =
  | { status: 'idle'; options: NameComboboxOption[] }
  | { status: 'loading'; options: NameComboboxOption[] }
  | { status: 'ready'; options: NameComboboxOption[] }
  | { status: 'error'; options: NameComboboxOption[] };

function normalizedText(value: string): string {
  return value
    .toLocaleLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');
}

function scoreText(value: string, query: string): number | null {
  const normalizedValue = normalizedText(value);
  const normalizedQuery = normalizedText(query.trim());

  if (!normalizedQuery) {
    return 0;
  }

  if (normalizedValue === normalizedQuery) {
    return 10_000;
  }

  if (normalizedValue.startsWith(normalizedQuery)) {
    return 8_000 - normalizedValue.length;
  }

  const wordIndex = normalizedValue.search(new RegExp(`(?:^|\\s)${escapeRegExp(normalizedQuery)}`));
  if (wordIndex >= 0) {
    return 7_000 - wordIndex;
  }

  const substringIndex = normalizedValue.indexOf(normalizedQuery);
  if (substringIndex >= 0) {
    return 6_000 - substringIndex;
  }

  let valueIndex = 0;
  let previousMatch = -2;
  let score = 1_000;

  for (const character of normalizedQuery) {
    const matchIndex = normalizedValue.indexOf(character, valueIndex);
    if (matchIndex < 0) {
      return null;
    }

    score += matchIndex === previousMatch + 1 ? 20 : 5;
    score -= matchIndex - valueIndex;
    previousMatch = matchIndex;
    valueIndex = matchIndex + 1;
  }

  return score - normalizedValue.length;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export function fuzzyRankOptions(
  options: NameComboboxOption[],
  query: string,
): NameComboboxOption[] {
  return options
    .map((option) => {
      const scores = [option.label, ...(option.keywords ?? [])]
        .map((value) => scoreText(value, query))
        .filter((score): score is number => score !== null);

      return {
        option,
        score: scores.length > 0 ? Math.max(...scores) : null,
      };
    })
    .filter(
      (candidate): candidate is { option: NameComboboxOption; score: number } =>
        candidate.score !== null,
    )
    .sort(
      (left, right) =>
        right.score - left.score || left.option.label.localeCompare(right.option.label),
    )
    .map(({ option }) => option);
}

export function NameCombobox({
  dependencyKey,
  entityName,
  inputValue,
  label,
  loadOptions,
  onInputChange,
  onSelectionChange,
  onSelectionResolved,
  placeholder,
  selectedValue,
  validationMessage,
}: NameComboboxProps) {
  const generatedId = useId();
  const inputId = `name-combobox-${generatedId}`;
  const listboxId = `${inputId}-listbox`;
  const feedbackId = `${inputId}-feedback`;
  const wrapperRef = useRef<HTMLDivElement>(null);
  const loadedRequestKeyRef = useRef<string | null>(null);
  const onSelectionResolvedRef = useRef(onSelectionResolved);
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [requestVersion, setRequestVersion] = useState(0);
  const [state, setState] = useState<OptionsState>({ status: 'idle', options: [] });
  const requestKey = `${dependencyKey}\u0000${inputValue.trim()}`;
  const shouldLoad =
    (open && loadedRequestKeyRef.current !== requestKey) ||
    (Boolean(selectedValue) && (state.status === 'idle' || state.status === 'loading'));

  useEffect(() => {
    onSelectionResolvedRef.current = onSelectionResolved;
  }, [onSelectionResolved]);

  useEffect(() => {
    if (!shouldLoad) {
      return;
    }

    const controller = new AbortController();
    setState((current) => ({ status: 'loading', options: current.options }));

    void loadOptions(inputValue.trim(), controller.signal)
      .then((options) => {
        if (controller.signal.aborted) {
          return;
        }

        loadedRequestKeyRef.current = requestKey;
        setState({ status: 'ready', options });
        if (selectedValue) {
          onSelectionResolvedRef.current(
            options.find((option) => option.value === selectedValue) ?? null,
          );
        }
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          loadedRequestKeyRef.current = requestKey;
          setState((current) => ({ status: 'error', options: current.options }));
        }
      });

    return () => controller.abort();
  }, [inputValue, loadOptions, requestKey, requestVersion, selectedValue, shouldLoad]);

  useEffect(() => {
    if (!open) {
      return;
    }

    function dismiss(event: PointerEvent) {
      if (!wrapperRef.current?.contains(event.target as Node)) {
        setOpen(false);
        setActiveIndex(-1);
      }
    }

    document.addEventListener('pointerdown', dismiss);
    return () => document.removeEventListener('pointerdown', dismiss);
  }, [open]);

  const selectedOption = state.options.find((option) => option.value === selectedValue);
  const searchQuery = selectedOption?.label === inputValue ? '' : inputValue;
  const rankedOptions = useMemo(
    () => fuzzyRankOptions(state.options, searchQuery),
    [searchQuery, state.options],
  );
  const activeOption = activeIndex >= 0 ? rankedOptions[activeIndex] : undefined;
  const optionsPending = open && loadedRequestKeyRef.current !== requestKey;

  function showOptions() {
    setOpen(true);
    setActiveIndex(-1);
  }

  function choose(option: NameComboboxOption) {
    onSelectionChange(option);
    setOpen(false);
    setActiveIndex(-1);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape' && open) {
      event.preventDefault();
      setOpen(false);
      setActiveIndex(-1);
      return;
    }

    if (event.key === 'Tab') {
      setOpen(false);
      setActiveIndex(-1);
      return;
    }

    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      showOptions();
      if (rankedOptions.length > 0) {
        setActiveIndex((current) => {
          if (event.key === 'ArrowDown') {
            return current < rankedOptions.length - 1 ? current + 1 : 0;
          }
          return current > 0 ? current - 1 : rankedOptions.length - 1;
        });
      }
      return;
    }

    if (event.key === 'Home' && open && rankedOptions.length > 0) {
      event.preventDefault();
      setActiveIndex(0);
      return;
    }

    if (event.key === 'End' && open && rankedOptions.length > 0) {
      event.preventDefault();
      setActiveIndex(rankedOptions.length - 1);
      return;
    }

    if (event.key === 'Enter' && open && activeOption) {
      event.preventDefault();
      choose(activeOption);
    }
  }

  function handleBlur(event: FocusEvent<HTMLDivElement>) {
    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
      setOpen(false);
      setActiveIndex(-1);
    }
  }

  const announcement = (() => {
    if (!open) {
      return selectedOption ? `${selectedOption.label} selected.` : '';
    }
    if (state.status === 'loading' || optionsPending) {
      return searchQuery
        ? `Matching ${entityName} options are loading.`
        : `Loading ${entityName} options.`;
    }
    if (state.status === 'error') {
      return `${label} options could not be loaded.`;
    }
    if (state.status === 'ready' && rankedOptions.length === 0) {
      return searchQuery
        ? `No such ${entityName} was found.`
        : `No ${entityName} options are available.`;
    }
    if (state.status === 'ready') {
      return `${rankedOptions.length} ${entityName} ${rankedOptions.length === 1 ? 'option' : 'options'} available.`;
    }
    return '';
  })();

  return (
    <div className="field name-combobox" onBlur={handleBlur} ref={wrapperRef}>
      <label htmlFor={inputId}>{label}</label>
      <div className="name-combobox__control">
        <input
          aria-activedescendant={activeOption ? `${listboxId}-${activeIndex}` : undefined}
          aria-autocomplete="list"
          aria-controls={listboxId}
          aria-describedby={validationMessage ? feedbackId : undefined}
          aria-expanded={open}
          aria-haspopup="listbox"
          aria-invalid={validationMessage ? 'true' : undefined}
          autoComplete="off"
          id={inputId}
          onChange={(event) => {
            onInputChange(event.target.value);
            showOptions();
          }}
          onFocus={() => {
            if (open) {
              showOptions();
            }
          }}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          role="combobox"
          type="text"
          value={inputValue}
        />
        {selectedValue ? (
          <button
            aria-label={`Clear ${label.toLocaleLowerCase()}`}
            className="name-combobox__clear"
            onClick={() => {
              onSelectionChange(null);
              setOpen(false);
            }}
            type="button"
          >
            Clear
          </button>
        ) : null}
        <button
          aria-label={`${open ? 'Hide' : 'Show'} ${label.toLocaleLowerCase()} options`}
          aria-expanded={open}
          className="name-combobox__toggle"
          onClick={() => {
            if (open) {
              setOpen(false);
              setActiveIndex(-1);
            } else {
              showOptions();
            }
          }}
          type="button"
        >
          <span aria-hidden="true">{open ? 'â–´' : 'â–¾'}</span>
        </button>
      </div>

      {validationMessage ? (
        <p className="field-error" id={feedbackId}>
          {validationMessage}
        </p>
      ) : null}

      <span aria-live="polite" className="visually-hidden">
        {announcement}
      </span>

      {open ? (
        <div className="name-combobox__popover">
          {state.status === 'loading' || optionsPending ? (
            <p className="name-combobox__state" role="status">
              {searchQuery
                ? `Matching ${entityName} options are loadingâ€¦`
                : `Loading ${entityName} optionsâ€¦`}
            </p>
          ) : null}

          {state.status === 'error' && !optionsPending ? (
            <div className="name-combobox__state name-combobox__state--error" role="alert">
              <p>{label} options could not be loaded.</p>
              <button
                className="button button--secondary"
                onClick={() => {
                  loadedRequestKeyRef.current = null;
                  setRequestVersion((version) => version + 1);
                }}
                type="button"
              >
                Retry {entityName} options
              </button>
            </div>
          ) : null}

          {state.status === 'ready' && !optionsPending && rankedOptions.length === 0 ? (
            <p className="name-combobox__state" role="status">
              {searchQuery
                ? `No such ${entityName} was found.`
                : `No ${entityName} options are available.`}
            </p>
          ) : null}

          {state.status === 'ready' && !optionsPending && rankedOptions.length > 0 ? (
            <ul
              aria-label={`${label} options`}
              className="name-combobox__options"
              id={listboxId}
              role="listbox"
            >
              {rankedOptions.map((option, index) => (
                <li
                  aria-selected={option.value === selectedValue}
                  className={
                    index === activeIndex
                      ? 'name-combobox__option is-active'
                      : 'name-combobox__option'
                  }
                  id={`${listboxId}-${index}`}
                  key={option.value}
                  onClick={() => choose(option)}
                  onMouseDown={(event) => event.preventDefault()}
                  onMouseEnter={() => setActiveIndex(index)}
                  role="option"
                >
                  <span>{option.label}</span>
                  {option.description ? <small>{option.description}</small> : null}
                  {option.value === selectedValue ? (
                    <small className="name-combobox__selected-marker">Selected</small>
                  ) : null}
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

import { act, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { useState } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { NameCombobox, type NameComboboxOption, fuzzyRankOptions } from './NameCombobox';

const options: NameComboboxOption[] = [
  { label: "Women's Premier League", value: 'competition-2' },
  { label: 'Premier Cricket League', value: 'competition-1' },
  { label: 'Super League', value: 'competition-3' },
];

function Harness({
  loadOptions = vi.fn().mockResolvedValue(options),
}: {
  loadOptions?: (query: string, signal: AbortSignal) => Promise<NameComboboxOption[]>;
}) {
  const [inputValue, setInputValue] = useState('');
  const [selectedValue, setSelectedValue] = useState('');

  return (
    <>
      <NameCombobox
        dependencyKey=""
        entityName="competition"
        inputValue={inputValue}
        label="Competition"
        loadOptions={loadOptions}
        onInputChange={(value) => {
          setInputValue(value);
          setSelectedValue('');
        }}
        onSelectionChange={(option) => {
          setInputValue(option?.label ?? '');
          setSelectedValue(option?.value ?? '');
        }}
        onSelectionResolved={() => undefined}
        placeholder="Type a competition name"
        selectedValue={selectedValue}
      />
      <div data-testid="selected-value">{selectedValue}</div>
    </>
  );
}

describe('NameCombobox', () => {
  it('fuzzy-ranks readable option names', () => {
    expect(fuzzyRankOptions(options, 'prem').map(({ label }) => label)).toEqual([
      'Premier Cricket League',
      "Women's Premier League",
    ]);
    expect(fuzzyRankOptions(options, 'spr')[0]?.label).toBe('Super League');
  });

  it('opens without typing, reports loading and selects an option directly', async () => {
    let resolveOptions!: (value: NameComboboxOption[]) => void;
    const loadOptions = vi.fn(
      (_query: string) =>
        new Promise<NameComboboxOption[]>((resolve) => {
          resolveOptions = resolve;
        }),
    );
    render(<Harness loadOptions={loadOptions} />);

    fireEvent.click(screen.getByRole('button', { name: 'Show competition options' }));
    expect(screen.getByRole('status')).toHaveTextContent('Loading competition options');

    await act(async () => resolveOptions(options));
    const listbox = await screen.findByRole('listbox', { name: 'Competition options' });
    fireEvent.click(within(listbox).getByRole('option', { name: 'Premier Cricket League' }));

    expect(screen.getByRole('combobox', { name: 'Competition' })).toHaveValue(
      'Premier Cricket League',
    );
    expect(screen.getByTestId('selected-value')).toHaveTextContent('competition-1');
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument();

    fireEvent.click(screen.getByRole('button', { name: 'Clear competition' }));
    expect(screen.getByRole('combobox', { name: 'Competition' })).toHaveValue('');
  });

  it('supports fuzzy typing, keyboard selection and dismissal', async () => {
    const loadOptions = vi.fn().mockResolvedValue(options);
    render(<Harness loadOptions={loadOptions} />);
    const combobox = screen.getByRole('combobox', { name: 'Competition' });

    fireEvent.change(combobox, { target: { value: 'prem' } });
    const ranked = await screen.findAllByRole('option');
    expect(ranked.map((option) => option.textContent)).toEqual([
      'Premier Cricket League',
      "Women's Premier League",
    ]);
    expect(loadOptions).toHaveBeenCalledWith('prem', expect.any(AbortSignal));

    fireEvent.keyDown(combobox, { key: 'ArrowDown' });
    expect(combobox).toHaveAttribute('aria-activedescendant');
    fireEvent.keyDown(combobox, { key: 'Enter' });
    expect(combobox).toHaveValue('Premier Cricket League');

    act(() => combobox.focus());
    fireEvent.keyDown(combobox, { key: 'ArrowDown' });
    fireEvent.keyDown(combobox, { key: 'Escape' });
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
    expect(combobox).toHaveFocus();
  });

  it('reports no matches and retries an option request failure', async () => {
    let resolveSearch!: (value: NameComboboxOption[]) => void;
    const loadOptions = vi
      .fn<(query: string, signal: AbortSignal) => Promise<NameComboboxOption[]>>()
      .mockRejectedValueOnce(new Error('offline'))
      .mockResolvedValueOnce(options)
      .mockImplementationOnce(
        () =>
          new Promise<NameComboboxOption[]>((resolve) => {
            resolveSearch = resolve;
          }),
      );
    render(<Harness loadOptions={loadOptions} />);

    fireEvent.click(screen.getByRole('button', { name: 'Show competition options' }));
    expect(await screen.findByRole('alert')).toHaveTextContent(
      'Competition options could not be loaded.',
    );
    fireEvent.click(screen.getByRole('button', { name: 'Retry competition options' }));
    await screen.findByRole('listbox');
    expect(loadOptions).toHaveBeenCalledTimes(2);

    fireEvent.change(screen.getByRole('combobox'), { target: { value: 'unknown' } });
    expect(screen.getByRole('status')).toHaveTextContent(
      /Matching competition options are loading/,
    );
    await act(async () => resolveSearch([]));
    await waitFor(() =>
      expect(screen.getByRole('status')).toHaveTextContent('No such competition was found.'),
    );
  });
});

