      }
      return;
    }

    if (event.key === 'Home' && open && rankedOptions.length > 0) {
      event.preventDefault();
      setActiveIndex(0);
      return;
    }

    if (event.key === 'End' && open && rankedOptions.length > 0) {
      event.preventDefault();
      setActiveIndex(rankedOptions.length - 1);
      return;
    }

    if (event.key === 'Enter' && open && activeOption) {
      event.preventDefault();
      choose(activeOption);
    }
  }

