  role: 'submitter' | 'admin';
  mode: 'file' | 'json';
}) {
  const client = useAuthenticatedApiClient();

  const [fixtureId, setFixtureId] = useState(
    fixtures[0]?.fixtureId ?? (mode === 'file' ? NEW_FIXTURE_VALUE : ''),
  );
  const [competitionState, setCompetitionState] = useState<CompetitionState>({ kind: 'idle' });
  const [scopeDialogState, setScopeDialogState] = useState<ScopeDialogState>({ kind: 'closed' });
  const [newFixture, setNewFixture] = useState<NewFixtureDraft>({
    competitionId: '',
    submittedCompetitionName: '',
    seasonName: '',
    startDate: '',
    endDate: '',
    homeTeamName: '',
    awayTeamName: '',
    matchType: 'T20',
    teamType: '',
    gender: '',
    ballsPerOver: '6',
    outcome: 'no result',
    winner: '',
    sourceVersion: '1',
    sourceRevision: '0',
  });
  const [eventJson, setEventJson] = useState(EMPTY_EVENTS);
  const [file, setFile] = useState<File | null>(null);
  const [decisionKey, setDecisionKey] = useState(newDecisionKey);
  const [result, setResult] = useState<ResultState>({ kind: 'idle' });

  const resultRegionRef = useRef<HTMLDivElement>(null);
  const scopeTriggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (scopeDialogState.kind === 'closed') return;

    const controller = new AbortController();
    setScopeDialogState({ kind: 'loading' });
    void competitionOptions(profile, controller.signal)
      .then((competitions) => {
        if (!controller.signal.aborted) setScopeDialogState({ kind: 'ready', competitions });
      })
      .catch(() => {
        if (!controller.signal.aborted) setScopeDialogState({ kind: 'error' });
      });
    return () => controller.abort();
  }, [profile, scopeDialogState.kind]);

  function closeScopeDialog() {
    setScopeDialogState({ kind: 'closed' });
    scopeTriggerRef.current?.focus();
  }

  useEffect(() => {
    if (mode !== 'file' || fixtureId !== NEW_FIXTURE_VALUE) return;
    const controller = new AbortController();
    setCompetitionState({ kind: 'loading' });
    void competitionOptions(profile, controller.signal)
      .then((competitions) => {
        setCompetitionState({ kind: 'ready', competitions });
        setNewFixture((draft) => {
          const submittedCompetition = competitions.find(
            (competition) =>
              competition.name.trim().toLocaleLowerCase() ===
              draft.submittedCompetitionName.trim().toLocaleLowerCase(),
          );
          return {
            ...draft,
            competitionId:
              submittedCompetition?.competitionId ??
              (competitions.some((competition) => competition.competitionId === draft.competitionId)
                ? draft.competitionId
                : (competitions[0]?.competitionId ?? '')),
          };
        });
      })
      .catch(() => {
        if (!controller.signal.aborted) setCompetitionState({ kind: 'error' });
      });
    return () => controller.abort();
  }, [fixtureId, mode, profile]);

  useEffect(() => {
    if (
      result.kind === 'accepted' ||
      result.kind === 'acceptedBatch' ||
      result.kind === 'rejected' ||
      result.kind === 'error'
    ) {
      resultRegionRef.current?.querySelector<HTMLElement>('[data-result-heading]')?.focus();
    }
  }, [result]);

  function resetResult() {
    if (result.kind !== 'idle' && result.kind !== 'submitting') {
      setResult({ kind: 'idle' });
    }
  }

  function beginNewFixtureProposal() {
    setFixtureId(NEW_FIXTURE_VALUE);
    setFile(null);
    setDecisionKey(newDecisionKey());
    resetResult();
  }

  function chooseExistingFixture() {
    if (!fixtures[0]) return;
    setFixtureId(fixtures[0].fixtureId);
    setFile(null);
    setDecisionKey(newDecisionKey());
    resetResult();
  }

  async function selectFile(selectedFile: File | null) {
    setFile(selectedFile);
    setDecisionKey(newDecisionKey());
    resetResult();
    if (!selectedFile || fixtureId !== NEW_FIXTURE_VALUE) return;

    try {
      const context = readSingleFixturePackageContext(
        selectedFile.name,
        await readFileText(selectedFile),
      );
      const matchingCompetition =
        competitionState.kind === 'ready'
          ? competitionState.competitions.find(
              (competition) =>
                competition.name.trim().toLocaleLowerCase() ===
                context.competitionName.trim().toLocaleLowerCase(),
            )
          : undefined;
      setNewFixture((draft) => ({
        ...draft,
        competitionId: matchingCompetition?.competitionId ?? draft.competitionId,
        submittedCompetitionName: context.competitionName,
        seasonName: context.seasonName,
        startDate: context.date,
        endDate: !draft.endDate || draft.endDate === draft.startDate ? context.date : draft.endDate,
        homeTeamName: context.teams[0] ?? '',
        awayTeamName: context.teams[1] ?? '',
      }));
    } catch (error) {
      setResult({
        kind: 'rejected',
        message:
          error instanceof SingleFixturePackageError
            ? error.message
            : 'The selected fixture package could not be read.',
        details: [],
      });
    }
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (
      result.kind === 'submitting' ||
      result.kind === 'accepted' ||
      result.kind === 'acceptedBatch'
    ) {
      return;
    }

    if (mode === 'file' && !file) {
      setResult({
        kind: 'rejected',
        message: 'Choose a JSON or CSV file before submitting.',
        details: [],
      });
      return;
    }

    setResult({ kind: 'submitting' });

    try {
      if (mode === 'file' && file) {
        if (!/\.(json|csv)$/i.test(file.name)) {
          throw new SubmissionInputError('Choose a JSON or CSV fixture package.');
        }
        if (file.size > MAX_BATCH_BYTES) {
          throw new BatchUploadInputError('The package is larger than the 50 MB upload limit.');
        }
        if (fixtureId === NEW_FIXTURE_VALUE) {
          const competition =
            competitionState.kind === 'ready'
              ? competitionState.competitions.find(
                  (candidate) => candidate.competitionId === newFixture.competitionId,
                )
              : undefined;
          if (!competition) {
            throw new SubmissionInputError('Choose an authorised competition for the new fixture.');
          }
          const contents = await readFileText(file);
          validateSingleFixturePackageContext(file.name, contents, {
            date: newFixture.startDate,
            teams: [newFixture.homeTeamName, newFixture.awayTeamName],
          });
          const proposalFile = createFixtureProposalBatchFile(file.name, contents, {
            competitionName: competition.name,
            seasonName: newFixture.seasonName,
            startDate: newFixture.startDate,
            homeTeamName: newFixture.homeTeamName,
            awayTeamName: newFixture.awayTeamName,
            proposal: {
              endDate: newFixture.endDate,
              matchType: newFixture.matchType,
              teamType: newFixture.teamType,
              gender: newFixture.gender,
              ballsPerOver: Number(newFixture.ballsPerOver),
              outcome: newFixture.outcome,
              ...(newFixture.outcome === 'won' ? { winner: newFixture.winner } : {}),
              sourceVersion: newFixture.sourceVersion,
              sourceRevision: Number(newFixture.sourceRevision),
            },
          });
          const response = await uploadBatch(
            client,
            competition.competitionId,
            proposalFile,
            decisionKey,
            undefined,
            FIXTURE_PROPOSAL_CONTRACT_VERSION,
          );

          invalidateBatchCollections();
          setResult({
            kind: 'acceptedBatch',
            receipt: response.data,
            fixtureLabel: `${newFixture.startDate} â€” ${newFixture.homeTeamName} v ${newFixture.awayTeamName} â€” ${competition.name}, ${newFixture.seasonName} (${newFixture.matchType})`,
            fixtureProposal: true,
          });
          return;
        }

        const fixture = fixtures.find((candidate) => candidate.fixtureId === fixtureId);
        if (!fixture?.competitionId) {
          throw new SubmissionInputError('Select an available fixture before uploading.');
        }
        validateSingleFixturePackage(file.name, await readFileText(file), fixture);
        const response = await uploadBatch(client, fixture.competitionId, file, decisionKey);

        invalidateBatchCollections();
        setResult({
          kind: 'acceptedBatch',
          receipt: response.data,
          fixtureLabel: formatFixtureOption(fixture),
        });
      } else {
        const fixture = fixtures.find((candidate) => candidate.fixtureId === fixtureId);
        if (!fixture?.competitionId) {
          throw new SubmissionInputError('Select an available fixture before submitting.');
        }

        if (role === 'admin') {
          const accepted = await submitLegacyAdminEvents(client, fixtureId, eventJson);
          setResult({
            kind: 'accepted',
            response: accepted.response,
            correctionContext: { events: accepted.events, fixture },
          });
        } else {
          const technicalFile = createTechnicalBatchFile(fixture, eventJson, decisionKey);
          const response = await uploadBatch(
            client,
            fixture.competitionId,
            technicalFile,
            decisionKey,
          );

          invalidateBatchCollections();
          setResult({
            kind: 'acceptedBatch',
            receipt: response.data,
            fixtureLabel: formatFixtureOption(fixture),
          });
        }
      }
    } catch (error) {
      if (error instanceof SubmissionInputError || error instanceof SingleFixturePackageError) {
        setResult({
          kind: 'rejected',
          message: error.message,
          details: [],
        });
      } else if (error instanceof BatchUploadInputError) {
        setResult({
          kind: 'rejected',
          message:
            error.message === 'Choose a JSON, CSV, or NDJSON package.'
              ? 'Choose a JSON or CSV fixture package.'
              : error.message,
          details: [],
        });
      } else if (error instanceof ApiResponseError && error.details) {
        setResult({
          kind: 'rejected',
          message: error.message,
          details: error.details,
        });
      } else if (mode === 'file' && error instanceof ApiResponseError && error.status === 409) {
        setResult({
          kind: 'error',
          message: `${error.message} Retry the unchanged file to reuse its receipt, or select a corrected file to start a replacement upload.`,
        });
      } else if (mode === 'file' && error instanceof ApiResponseError && error.status === 413) {
        setResult({
          kind: 'error',
          message: 'The fixture package exceeds the 50 MB upload limit.',
        });
      } else if (error instanceof ApiResponseError && error.status === 403) {
        setResult({
          kind: 'error',
          message:
            'The backend did not permit this submission. Your approval or fixture scope may have changed.',
        });
      } else {
        setResult({
          kind: 'error',
          message:
            error instanceof ApiResponseError
              ? mode === 'file' && error.status === 503
                ? 'Fixture-package storage is temporarily unavailable. Retry the same file safely.'
                : error.message
              : 'The submission could not be completed. Please try again.',
        });
      }
    }
  }

  if (fixtures.length === 0 && mode === 'json') {
    return (
      <div className="state-message" role="status">
        <h2>No in-scope fixtures</h2>
        <p>
          Your account has submission access, but it currently has no available fixtures in its
          scope.
        </p>
      </div>
    );
  }

  const resultDescriptionId =
    result.kind === 'rejected' ? 'submission-validation-results' : undefined;

  const competitions = [...new Set(fixtures.map((fixture) => fixture.competitionName))];
  const completed = result.kind =…4121 tokens truncated…competitionId) => {
            const response = await publicReadApi.getCompetition(competitionId, signal);
            return response.data;
          }),
        );
  return competitions.sort((left, right) => left.name.localeCompare(right.name));
}

export type PackageUploadScope = 'season' | 'catalogue';

export function BatchUploadWorkflow({
  profile,
  scope,
  replacement,
}: {
  profile: CurrentUserProfile;
  scope: PackageUploadScope;
  replacement?: { batchReference: string; competitionId: string };
}) {
  const client = useAuthenticatedApiClient();
  const [access, setAccess] = useState<AccessState>({ kind: 'loading' });
  const [competitionId, setCompetitionId] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [upload, setUpload] = useState<UploadState>({ kind: 'idle' });
  const resultRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const controller = new AbortController();
    setAccess({ kind: 'loading' });
    void competitionOptions(profile, controller.signal)
      .then((competitions) => {
        setAccess({ kind: 'ready', competitions });
        setCompetitionId(
          (replacement &&
            competitions.some(
              (competition) => competition.competitionId === replacement.competitionId,
            ) &&
            replacement.competitionId) ||
            competitions[0]?.competitionId ||
            '',
        );
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          setAccess({ kind: 'error', message: 'Your upload scope could not be loaded.' });
        }
      });
    return () => controller.abort();
  }, [profile, replacement]);

  useEffect(() => {
    if (upload.kind === 'accepted' || upload.kind === 'error') {
      resultRef.current?.querySelector<HTMLElement>('[data-upload-result]')?.focus();
    }
  }, [upload]);

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (upload.kind === 'uploading' || upload.kind === 'accepted') return;
    if (!file) {
      setUpload({ kind: 'error', message: 'Choose a package before uploading.' });
      return;
    }
    if (!competitionId) {
      setUpload({ kind: 'error', message: 'Choose an authorised competition.' });
      return;
    }
    setUpload({ kind: 'uploading' });
    try {
      const response = await uploadBatch(
        client,
        competitionId,
        file,
        await batchUploadIdempotencyKey(competitionId, file),
        replacement?.batchReference,
      );
      invalidateBatchCollections();
      const competition =
        access.kind === 'ready'
          ? access.competitions.find((option) => option.competitionId === competitionId)
          : undefined;
      setUpload({
        kind: 'accepted',
        receipt: response.data,
        context:
          scope === 'season'
            ? `${competition?.name ?? 'Selected competition'} Â· season named in package`
            : `${competition?.name ?? 'Selected competition'} Â· seasons named in package`,
      });
    } catch (error) {
      const message =
        error instanceof BatchUploadInputError
          ? error.message
          : error instanceof ApiResponseError && error.status === 409
            ? replacement
              ? `${error.message} Refresh submission history to check whether another replacement was submitted.`
              : `${error.message} Start a requested correction from the original batch in submission history.`
            : error instanceof ApiResponseError && error.status === 413
              ? 'The server rejected this package because it exceeds the 50 MB limit.'
              : error instanceof ApiResponseError && error.status === 503
                ? 'Upload storage is temporarily unavailable. Retry this same file to reuse the upload request safely.'
                : 'The upload could not be completed. Retry this same file safely.';
      setUpload({ kind: 'error', message });
    }
  }

  const busy = upload.kind === 'uploading';
  const completed = upload.kind === 'accepted';
  const scopeLabel = scope === 'season' ? 'season' : 'back catalogue';

  return (
    <div className="batch-upload-workflow">
      <section className="batch-guidance" aria-labelledby="batch-guidance-title">
        <h2 id="batch-guidance-title">
          Before you upload a {scope === 'season' ? 'season' : 'back catalogue'}
        </h2>
        <p>
          Upload one JSON, CSV spreadsheet, or NDJSON file up to 50 MB and 50,000 delivery events.
          At most three uploads may be processing at once. Each upload is checked in the background
          before it can be reviewed and published.
        </p>
        <p>Every package must include:</p>
        <ul>
          <li>
            <code>contractVersion</code> and a stable <code>packageId</code>;
          </li>
          <li>competition and season names or stable provider references;</li>
          <li>fixture date and team names, then innings number and batting team; and</li>
          <li>each delivery&apos;s reference, order, participants and runs.</li>
        </ul>
        <p>
          Stable provider references are optional when the documented readable context is supplied.
        </p>
        <div className="batch-guidance__actions">
          <a className="button button--secondary" href="/season-upload-template.json" download>
            Download JSON template
          </a>
          <a className="button button--secondary" href="/season-upload-template.csv" download>
            Download spreadsheet template
          </a>
        </div>
      </section>

      {access.kind === 'loading' ? (
        <div className="state-message" role="status">
          <h2>Loading upload choices</h2>
          <p>Checking your competition scopeâ€¦</p>
        </div>
      ) : access.kind === 'error' ? (
        <div className="state-message state-message--error" role="alert">
          <h2>Upload choices unavailable</h2>
          <p>{access.message}</p>
        </div>
      ) : access.competitions.length === 0 ? (
        <div className="state-message" role="status">
          <h2>No authorised competitions</h2>
          <p>Ask an administrator to assign a competition before uploading.</p>
        </div>
      ) : (
        <form className="submission-form batch-upload-form" onSubmit={submit}>
          {replacement ? (
            <div className="state-message" role="status">
              <h2>Corrected replacement upload</h2>
              <p>
                This package will replace correction-requested batch{' '}
                <code>{replacement.batchReference}</code>. The original remains in submission
                history with a link to this replacement.
              </p>
            </div>
          ) : null}
          <div className="submission-field">
            <label htmlFor="batch-competition">Competition</label>
            <select
              id="batch-competition"
              value={competitionId}
              disabled={busy || completed || Boolean(replacement)}
              onChange={(event) => {
                setCompetitionId(event.target.value);
                setUpload({ kind: 'idle' });
              }}
            >
              {access.competitions.map((competition) => (
                <option value={competition.competitionId} key={competition.competitionId}>
                  {competition.name}
                </option>
              ))}
            </select>
            <p className="field-help">Only competitions authorised by the server appear here.</p>
          </div>

          {scope === 'season' ? (
            <p className="field-help">
              The season name and reference inside the package are authoritative and are validated
              during processing. Known seasons are not selected during upload.
            </p>
          ) : (
            <p className="field-help">
              Each season is identified by its readable name inside the package.
            </p>
          )}

          <div className="submission-field">
            <label htmlFor="batch-file">
              {scope === 'season' ? 'Season' : 'Back catalogue'} package
            </label>
            <input
              id="batch-file"
              type="file"
              accept=".json,application/json,.csv,text/csv,.ndjson,application/x-ndjson"
              disabled={busy || completed}
              aria-describedby="batch-file-help"
              aria-invalid={upload.kind === 'error'}
              onChange={(event) => {
                setFile(event.target.files?.[0] ?? null);
                setUpload({ kind: 'idle' });
              }}
            />
            <p id="batch-file-help" className="field-help">
              JSON, CSV or NDJSON; maximum {MAX_BATCH_BYTES / 1024 / 1024} MB.{' '}
              {replacement
                ? 'Selecting the corrected file creates the linked replacement. '
                : 'Start a requested correction from the original batch in submission history. '}
              Retrying unchanged content, including after a page refresh and reselecting the file,
              reuses the same request and receipt.
            </p>
            {file ? <p className="field-help">Selected: {file.name}</p> : null}
          </div>

          {upload.kind !== 'accepted' ? (
            <button className="button button--primary" type="submit" disabled={busy}>
              {busy ? 'Uploading packageâ€¦' : `Upload ${scopeLabel} package`}
            </button>
          ) : null}

          {busy ? (
            <div className="batch-upload-progress" role="status">
              <progress aria-label="Upload progress" />
              <p>Uploading {file?.name}. Keep this page open until the durable receipt appears.</p>
            </div>
          ) : null}

          <div ref={resultRef}>
            {upload.kind === 'error' ? (
              <div className="submission-result submission-result--error" role="alert">
                <h2 tabIndex={-1} data-upload-result>
                  {scope === 'season' ? 'Season' : 'Back catalogue'} upload failed
                </h2>
                <p>{upload.message}</p>
              </div>
            ) : upload.kind === 'accepted' ? (
              <div className="submission-result" role="status">
                <h2 tabIndex={-1} data-upload-result>
                  {scope === 'season' ? 'Season upload received' : 'Back catalogue upload received'}
                </h2>
                <p>
                  Your {scopeLabel} file has been received. The platform is checking it in the
                  background; it is not published yet. You may leave this page safely.
                </p>
                <p>
                  Next: open the submission report to see processing progress and any validation
                  problems. If corrections are needed, update the file and submit it again. After
                  validation succeeds, an administrator can review it for publication.
                </p>
                <dl className="submission-reference">
                  <div>
                    <dt>Submission receipt</dt>
                    <dd>{upload.receipt.batchReference}</dd>
                  </div>
                  <div>
                    <dt>Status</dt>
                    <dd>Received â€” validation pending</dd>
                  </div>
                  <div>
                    <dt>Context</dt>
                    <dd>{upload.context}</dd>
                  </div>
                  <div>
                    <dt>Received</dt>
                    <dd>{new Date(upload.receipt.receivedAt).toLocaleString()}</dd>
                  </div>
                </dl>
                <Link
                  className="button button--primary"
                  to={`/submissions/batches/${upload.receipt.batchReference}`}
                >
                  View submission report
                </Link>
                <Link className="button button--secondary" to="/submissions/batches">
                  View submission history
                </Link>
              </div>
            ) : null}
          </div>
        </form>
      )}
    </div>
  );
}

