  fixtures: Fixture[],
  proposal: NewFixtureDraft,
): Fixture | undefined {
  const proposedTeams = [proposal.homeTeamName, proposal.awayTeamName]
    .map(normaliseFixtureValue)
    .sort()
    .join('|');

  if (
    !proposal.competitionId ||
    !proposal.seasonName.trim() ||
    !proposal.startDate ||
    proposedTeams === '|'
